int64_t* merge3Sorted(int64_t* p, size_t p_len, int64_t* q, size_t q_len, int64_t* c, size_t c_len, size_t* result_len) {
    size_t total_len = p_len + q_len + c_len;
    int64_t* result = (int64_t*)malloc(total_len * sizeof(int64_t));
    if (result == NULL) {
        *result_len = 0;
        return NULL;
    }

    size_t i = 0, j = 0, k = 0, idx = 0;

    while (i < p_len && j < q_len) {
        if (p[i] <= q[j]) {
            result[idx++] = p[i++];
        } else {
            result[idx++] = q[j++];
        }
    }
    while (i < p_len) result[idx++] = p[i++];
    while (j < q_len) result[idx++] = q[j++];

    int64_t* merged_ab = (int64_t*)malloc(idx * sizeof(int64_t));
    if (merged_ab == NULL) {
        free(result);
        *result_len = 0;
        return NULL;
    }
    memcpy(merged_ab, result, idx * sizeof(int64_t));

    size_t ab_len = idx;
    i = 0;
    j = 0;
    idx = 0;

    while (i < ab_len && j < c_len) {
        if (merged_ab[i] <= c[j]) {
            result[idx++] = merged_ab[i++];
        } else {
            result[idx++] = c[j++];
        }
    }
    while (i < ab_len) result[idx++] = merged_ab[i++];
    while (j < c_len) result[idx++] = c[j++];

    free(merged_ab);
    *result_len = idx;
    return result;
}

