import java.util.*;

public class Solution {
    public static int[] merge3Sorted(int[] p, int[] q, int[] c) {
        int[] mergedPQ = mergeTwoSorted(p, q);
        return mergeTwoSorted(mergedPQ, c);
    }

    private static int[] mergeTwoSorted(int[] a, int[] b) {
        int[] result = new int[a.length + b.length];
        int i = 0, j = 0, k = 0;

        while (i < a.length && j < b.length) {
            if (a[i] <= b[j]) {
                result[k++] = a[i++];
            } else {
                result[k++] = b[j++];
            }
        }

        while (i < a.length) {
            result[k++] = a[i++];
        }

        while (j < b.length) {
            result[k++] = b[j++];
        }

        return result;
    }

    public static void main(String[] args) {
        // Test case 1: normal case
        int[] p1 = {1, 3, 5};
        int[] q1 = {2, 4, 6};
        int[] c1 = {0, 7, 8};
        System.out.println(Arrays.toString(merge3Sorted(p1, q1, c1)));

        // Test case 2: empty arrays
        int[] p2 = {};
        int[] q2 = {1, 2, 3};
        int[] c2 = {};
        System.out.println(Arrays.toString(merge3Sorted(p2, q2, c2)));

        // Test case 3: all empty
        int[] p3 = {};
        int[] q3 = {};
        int[] c3 = {};
        System.out.println(Arrays.toString(merge3Sorted(p3, q3, c3)));

        // Test case 4: arrays with zeros and negatives
        int[] p4 = {-5, 0, 3};
        int[] q4 = {-2, 1};
        int[] c4 = {-10, 5, 10};
        System.out.println(Arrays.toString(merge3Sorted(p4, q4, c4)));

        // Test case 5: different lengths
        int[] p5 = {10, 20};
        int[] q5 = {5, 15, 25, 35};
        int[] c5 = {0, 30, 40};
        System.out.println(Arrays.toString(merge3Sorted(p5, q5, c5)));
    }
}
